 function vesselContents(v){const d=current().drink,rows=d.pours.filter(p=>p.location===v);return '<section class="bar-vessel-contents" aria-live="polite"><b>'+esc(P.vesselNames[v])+' 안의 재료</b>'+(rows.length?'<ul>'+rows.map(p=>'<li><span>'+esc(D.ingredients[p.id][0])+'</span><strong>'+P.fmt(p.n,p.unit)+'</strong></li>').join('')+'</ul>':'<p>비어 있음</p>')+'<small>'+(d.ice[v]?'얼음 있음':'얼음 없음')+(v==='glass'&&d.garnish!=='none'?' · '+esc(D.garnishes[d.garnish]):'')+'</small></section>'; }

 let guidedAction=null;
 function preparationControls(){const p=current().practice;if(!p)return '<p class="bar-quick-status">새 과제부터 준비 동작과 돌발 상황이 적용됩니다.</p>';
  return '<div class="bar-training-card"><b>시작 전 준비</b><p>손·복장과 재료 위치를 확인하세요.</p>'+quickGrid(B.prepKeys(current()).map(k=>btn((p.prep[k]?'✓ ':'')+B.precautionNames[k],'precaution','data-key="'+k+'" '+(p.prep[k]?'disabled':''))).join(''))+'<small>'+(B.prepared(current())?'준비 완료':'준비를 마치면 조주 시간이 시작됩니다.')+'</small><details class="bar-safety-index"><summary>주의 동작·돌발 목록</summary><p>계량: 재료명·라벨, 병 열기, 지거 수평·몸 앞, 재료 교체 시 헹굼.<br>준비: 잔·도구 점검, 얼음 집게, 도마 고정·칼 파지.<br>조주·제출: 셰이커 밀착·양손·방향, 스트레이너 고정, 스템 잡기, 장식 집게·픽, 최종 확인·잔 물기·병뚜껑.</p><p>돌발 8종: 주스 넘침 · 셰이커 쏟음 · 가니시 떨어짐 · 탄산 거품 · 금 간 잔 · 집게 떨어짐 · 도마 미끄러짐 · 코르크 부스러짐.</p></details></div>';
 }
 function checksMarkup(event,needed){return '<div class="bar-training-card"><b>'+(event.type==='measure'?'계량 전 확인':event.type==='direct'?'붓기 전 확인':event.type==='transfer'?'따르기 전 확인':event.type==='mix'?'혼합 전 확인':event.type==='submit'?'제출 전 확인':event.type==='cut'?'칼질 전 확인':'작업 전 확인')+'</b>'+quickGrid(needed.map(k=>k==='pace'?btn('병을 받쳐 천천히','precaution','data-key="steady" data-id="'+event.id+'"')+btn('한 손으로 급하게','precaution','data-key="fast" data-id="'+event.id+'"'):btn(B.precautionNames[k],'precaution','data-key="'+k+'" '+(event.id?'data-id="'+event.id+'"':''))).join(''))+'</div>';}
 function episodeControls(){const i=current().practice?.incident;if(!i)return '';
  let actions='';
  if(i.kind==='overpour')actions=(!i.emptied?btn('지거 비우기','recovery','data-choice="empty"','primary'):'')+(!i.wiped?btn('행주로 흘린 곳 닦기','recovery','data-choice="wipe"'):'')+(!i.emptied?btn('눈대중으로 덜기','recovery','data-choice="guess"'):'');
  if(i.kind==='shakerLeak')actions=(!i.wiped?btn('행주로 작업대 닦기','recovery','data-choice="wipe"','primary'):'')+(!i.washed?btn('싱크대에서 셰이커 헹구기','recovery','data-choice="wash"'):'')+btn('계속 흔들기','recovery','data-choice="keepShaking"');
  if(i.kind==='garnishDrop')actions=btn('버리고 새로 준비','recovery','data-choice="discard"','primary')+btn('그대로 다시 사용','recovery','data-choice="reuse"');
  if(i.kind==='glassChip'||i.kind==='corkBreak')actions=btn('감독관에게 알리고 교체','recovery','data-choice="replace"','primary')+btn('그대로 사용','recovery','data-choice="ignore"');
  if(i.kind==='tongsDrop')actions=btn('싱크대에서 집게 세척','recovery','data-choice="wash-tongs"','primary')+btn('주워서 바로 사용','recovery','data-choice="ignore"');
  if(i.kind==='wetBoard')actions=(!i.knifeDown?btn('칼부터 내려놓기','recovery','data-choice="knife-down"','primary'):'')+(!i.dried?btn('도마 물기 닦기','recovery','data-choice="dry-board"'):'')+(!i.secured?btn('도마 받침 고정','recovery','data-choice="secure-board"'):'')+btn('그대로 칼질','recovery','data-choice="ignore"');
  if(i.kind==='foam')actions=btn('병을 세워 거품 가라앉히기','recovery','data-choice="wait"','primary')+btn('멈추지 않고 붓기','recovery','data-choice="keepPouring"');
  return '<div class="bar-training-card bar-incident" role="status"><b>돌발! '+esc(i.title)+'</b><p>'+esc(i.description)+'</p>'+((i.emptied||i.wiped||i.washed)?'<small>'+[i.emptied?'✓ 지거 비움':'',i.wiped?'✓ 흘린 곳 닦음':'',i.washed?'✓ 셰이커 헹굼':''].filter(Boolean).join(' · ')+'</small>':'')+quickGrid(actions)+'</div>';
 }
 function trainingStatus(){const p=current().practice;if(!p)return '';return p.incident?'돌발!':B.prepared(current())?'준비 ✓':'준비 '+Object.values(p.prep).filter(Boolean).length+'/'+B.prepKeys(current()).length;}
 function openTraining(){guidedAction=null;const p=current().practice;selected=p?.incident?.anchor||'@sink';panelView=p?.incident?'incident':'prepare';refreshPanel();}

 const menuLink=(label,id)=>btn(label,'menu-view','data-id="'+id+'"');
 const quickGrid=html=>'<div class="bar-quick-grid">'+html+'</div>';
 function quickTarget(){return '<label class="bar-quick-target">붓는 곳<select id="bar-target" aria-label="붓는 곳">'+Object.entries(P.vesselNames).map(([id,name])=>option(id,name,current().drink.vessel)).join('')+'</select></label>';}
 function quickCup(){const c=current().drink.cup;return c?'<div class="bar-jigger-filled">'+A.jiggerFill(c.side,c.n)+'<div><b>'+esc(D.ingredients[c.id][0])+'</b>'+btn(P.fmt(c.n,c.unit),'cancel-measure','aria-label="'+P.fmt(c.n,c.unit)+' 계량 취소"','bar-filled-amount')+'<span>'+Math.round(c.n*3000)/100+' mL</span></div></div>'+quickTarget()+quickGrid(btn('지거 → 선택한 곳','act','data-type="pour"','primary')+btn('뒤집은 스푼에 붓기','float')+btn('지거 비우기','act','data-type="emptyCup"')):measureId?measureControls(measureId):'<p class="bar-quick-status">계량할 병을 눌러 주세요.</p>';}
 function measureControls(id){
  if(current().drink.cup)return quickCup();
  const needed=B.requirements(current(),{type:'measure',id});if(needed.length)return needed.some(k=>B.prepKeys(current()).includes(k))?preparationControls():checksMarkup({type:'measure',id},needed);
  return '<div class="bar-quick-grid">'+btn('작은 쪽 · 1 oz','side','data-id="small" aria-pressed="'+(side==='small')+'"')+btn('큰 쪽 · 1½ oz','side','data-id="large" aria-pressed="'+(side==='large')+'"')+'</div><div class="bar-jigger-measure"><div class="bar-jigger-picker" tabindex="0" role="slider" aria-label="지거 용량" aria-valuemin="0" aria-valuemax="'+(side==='large'?1.5:1)+'" aria-valuenow="'+quantity+'" aria-valuetext="'+(quantity?P.fmt(quantity,'oz'):'비어 있음')+'" aria-orientation="vertical" data-side="'+side+'">'+A.jiggerFill(side,quantity)+'</div><div class="bar-jigger-amounts">'+[...P.ticks[side]].reverse().map(n=>btn(P.fmt(n,'oz')+' <small>'+Math.round(n*3000)/100+' mL</small>','measure','data-id="'+id+'" data-n="'+n+'" aria-pressed="'+(quantity===n)+'"')).join('')+'</div></div><output class="bar-measure-readout" aria-live="polite">'+(quantity?P.fmt(quantity,'oz')+' · '+Math.round(quantity*3000)/100+' mL':'비어 있음')+'</output>'+btn('지거 채우기','fill-jigger','data-id="'+id+'" '+(quantity?'':'disabled'),'primary');
 }
 function setQuantity(n){quantity=n;const pane=document.getElementById('bar-panel');if(!pane)return;const picker=pane.querySelector('.bar-jigger-picker');if(picker){picker.innerHTML=A.jiggerFill(side,n);picker.setAttribute('aria-valuenow',n);picker.setAttribute('aria-valuetext',n?P.fmt(n,'oz'):'비어 있음');}pane.querySelectorAll('[data-bar="measure"]').forEach(el=>el.setAttribute('aria-pressed',String(Number(el.dataset.n)===n)));const output=pane.querySelector('.bar-measure-readout');if(output)output.textContent=n?P.fmt(n,'oz')+' · '+Math.round(n*3000)/100+' mL':'비어 있음';const fill=pane.querySelector('[data-bar="fill-jigger"]');if(fill)fill.disabled=!n;}
 function returnToMeasure(c){if(c){measureId=c.id;side=c.side;selected='b:'+c.id;}quantity=0;panelView=current().practice?.incident?'incident':'measure';refresh();}
 function changeZoom(value,anchor){const pane=document.getElementById('bar-stage-scroll'),scene=main.querySelector('.bar-scene');if(!pane||!scene)return;const before=scene.getBoundingClientRect(),view=pane.getBoundingClientRect(),px=anchor?.x??view.left+view.width/2,py=anchor?.y??view.top+view.height/2,nx=(px-before.left)/before.width,ny=(py-before.top)/before.height;zoom=Math.max(1,Math.min(4,value));scene.style.setProperty('--scene-zoom',zoom);const after=scene.getBoundingClientRect();if(zoom===1){pane.scrollLeft=0;pane.scrollTop=0;main.querySelector('.bar-stage-card')?.scrollIntoView({block:'start',behavior:'instant'});}else{pane.scrollLeft+=after.left+after.width*nx-px;pane.scrollTop+=after.top+after.height*ny-py;}const output=document.getElementById('bar-zoom-value');if(output)output.textContent=Math.round(zoom*100)+'%';placePanel();}
 function quickFruit(view){const f=current().fruit;
  if(!f)return quickGrid(Object.entries(B.fruitNames).map(([id,name])=>btn(name,'fruit-start','data-id="'+id+'"')).join(''));
  const citrus=['lemon','lime','orange'].includes(f.kind),plain=['whole','halfLong','halfCross'].includes(f.form);
  const status='<p class="bar-quick-status">'+esc(B.fruitNames[f.kind])+' · '+esc(B.forms[f.form]||'착즙한 반쪽')+(plain?' · '+(f.angle?'가로':'세로'):'')+'</p>';
  if(view==='cut')return status+quickGrid(btn('90° 돌리기','act','data-type="rotate"')+(!f.trimmed?btn('끝 정리','cut','data-id="trim"'):'')+(f.form==='whole'?btn('반으로 자르기','cut','data-id="half"'):'')+(plain?menuLink('슬라이스 자르기','slice')+btn('웨지 자르기','cut','data-id="wedge"'):'')+(citrus?btn('껍질 뜨기','cut','data-id="peel"'):'')+(f.form==='peel'?btn('흰 부분 다듬기','cut','data-id="pith"')+btn('껍질 비틀기','act','data-type="twist"'):'')+menuLink('장식 조립 →','garnish'));
  if(view==='slice')return '<label>슬라이스 두께<select id="bar-thickness" aria-label="슬라이스 두께">'+[2,3,4,6,8].map(n=>option(String(n),n+' mm',String(f.thickness))).join('')+'</select></label>'+btn('슬라이스 자르기','cut','data-id="slice"');
  if(view==='garnish')return status+quickGrid((['slice','wedge','wheel'].includes(f.form)&&!f.slit?btn('잔에 걸 칼집','cut','data-id="slit"'):'')+(!f.picked?btn('과일 조각을 픽에','act','data-type="pickFruit"'):'')+(['slice','wedge'].includes(f.form)&&!f.cherry?btn('체리 꽂아 조립','act','data-type="addCherry"'):'')+(f.kind==='lemon'&&f.cherry&&!f.wrapped?btn('체리 감싸 말기','act','data-type="wrap"'):'')+btn('완성한 장식 올리기','act','data-type="garnishFruit"','primary'));
  if(view==='juice')return quickTarget()+quickGrid(btn('단면 십자 칼집','cut','data-id="cross"')+btn('레몬 반 개 짜기','act','data-type="squeeze"')+btn('잔 가장자리 적시기','act','data-type="wetRim"')+btn('소금 리밍','act','data-type="salt"'));
  if(['cherry','olive'].includes(f.kind))return quickGrid((!f.picked?btn('픽에 꽂기','act','data-type="pickFruit"'):'')+btn('장식 올리기','act','data-type="garnishFruit"'));
  return status+quickGrid(menuLink('자르기 · 돌리기','cut')+menuLink('장식 조립','garnish')+(['lemon','lime'].includes(f.kind)?menuLink('착즙 · 리밍','juice'):'')+(f.form!=='whole'?btn('새 '+B.fruitNames[f.kind],'fruit-start','data-id="'+f.kind+'"'):''));
 }
 function quickMain(o){const s=current(),d=s.drink,id=o.id,hasLiquid=d.pours.some(p=>p.location===d.vessel);
  if(o.type==='ingredient')return quickGrid(menuLink('지거에 계량','measure')+menuLink('바로 붓기','direct')+(d.cup?menuLink('담긴 지거 붓기','cup'):'')+(s.practice?.version===2&&s.practice.bottles[id]?.open?btn('병뚜껑 닫기','precaution','data-key="bottleClose" data-id="'+id+'"'):''));
  if(o.type==='fruit'||['knife','board','pick'].includes(id))return quickFruit('');
  if(o.type==='glass')return quickGrid(btn(d.ice.glass?'칠링 얼음 비우기':'잔 칠링','act','data-type="'+(d.ice.glass?'emptyIce':'chill')+'"')+(d.ice.glass?btn('잔 얼음 → 블렌더','act','data-type="iceToBlender"'):'')+btn('코스터로 옮기기','coaster')+btn('제출하기','act','data-type="submit"')+menuLink('담긴 재료','contents')+menuLink('세척 · 이동','more'));
  if(id==='towel')return btn('작업대 닦기','wipe','data-key="work"');
  if(id==='nutmeg')return btn('넛메그 한 꼬집','act','data-type="nutmeg"');
  if(id==='sugarCubes')return quickTarget()+btn('각설탕 1개 넣기','sugar-cube');
  if(id==='jigger')return quickCup();
  if(id==='rimmer')return quickGrid(btn('잔 가장자리 적시기','act','data-type="wetRim"')+btn('소금 리밍','act','data-type="salt"'));
  if(id==='ice'||id==='crushed'||id==='tongs')return quickTarget()+quickGrid(btn(id==='crushed'?'분쇄 얼음 넣기':'집게로 얼음 넣기','ice','data-crushed="'+(id==='crushed')+'"')+btn('집게로 제공 잔 칠링','act','data-type="chill"')+(id==='tongs'?menuLink('장식 조립','garnish'):btn('잔 얼음 → 블렌더','act','data-type="iceToBlender"')));
  if(id==='spoon')return quickTarget()+quickGrid(btn('설탕 녹이기','act','data-type="dissolve"')+btn('가볍게 젓기 · Build','mix','data-id="Build"')+btn('저어 섞기 · Stir','mix','data-id="Stir"')+menuLink('세척 · 이동','more'));
  if(['mixing','shaker','blender','strainer'].includes(id)){let actions='';
   if(!d.ice[d.vessel])actions+=btn('얼음 넣기','act','data-type="ice"');
   if(id==='shaker'||id==='blender'){actions+=btn('뚜껑 '+(s.closed[id]?'열기':'닫기'),'lid','data-id="'+id+'" data-closed="'+(!s.closed[id])+'"');if(s.closed[id])actions+=btn(id==='shaker'?'흔들기 · Shake':'갈기 · Blend','mix','data-id="'+(id==='shaker'?'Shake':'Blend')+'"');if(id==='shaker'&&s.closed[id]&&!s.capOff)actions+=btn('윗캡 열기','act','data-type="cap"');}
   if(id==='mixing')actions+=btn('저어 섞기 · Stir','mix','data-id="Stir"')+(d.ice.mixing?btn('녹은 물만 버리기','act','data-type="drain"'):'');
   if(hasLiquid||id==='strainer')actions+=menuLink('잔에 따르기','transfer')+menuLink('담긴 재료','contents');
   return quickGrid(actions+menuLink('세척 · 이동','more'));
  }
  return menuLink('세척 · 이동','more');
 }
 function panel(){const s=current(),o=O.byKey[selected]||(selected==='@sink'?{name:'시작 전 준비',id:'sink',type:'sink'}:null);if(!o)return '';let body='';
  if(s.drink.submitted)body='<p class="bar-quick-status">제출한 잔입니다.</p>';
  else if(s.practice?.incident)body=episodeControls();
  else if(panelView==='prepare'||o.type==='sink')body=preparationControls();
  else if(panelView==='checks'&&guidedAction){const needed=B.requirements(s,guidedAction);body=needed.length?checksMarkup(guidedAction,needed):btn('확인 완료 · 계속하기','guided-continue','','primary');}
  else if(panelView==='measure')body=measureControls(o.type==='ingredient'?o.id:measureId);
  else if(panelView==='direct'&&B.requirements(s,{type:'direct',id:o.id}).length){const needed=B.requirements(s,{type:'direct',id:o.id});body=needed.some(k=>B.prepKeys(current()).includes(k))?preparationControls():checksMarkup({type:'direct',id:o.id},needed);}
  else if(panelView==='direct')body=quickTarget()+'<label>양·단위<select id="bar-direct" aria-label="양·단위">'+['1/3 part','Fill','On Top','1 tsp','1/2 tsp','2 tsp','1 dash','1/4 oz','1/2 oz','3/4 oz','1 oz','1 1/2 oz'].map(q=>option(q,q,directValue)).join('')+'</select></label>'+quickGrid(btn('바로 넣기','direct','data-id="'+o.id+'"')+btn('스푼으로 층 쌓기','direct-float','data-id="'+o.id+'"'));
  else if(panelView==='cup')body=quickCup();
  else if(['fruit','cut','slice','garnish','juice'].includes(panelView))body=quickFruit(panelView);
  else if(panelView==='transfer')body=quickGrid(btn('얼음 걸러 따르기','transfer','data-id="strain"')+btn('얼음째 모두 따르기','transfer','data-id="all"'));
  else if(panelView==='contents')body=vesselContents(s.drink.vessel);
  else if(panelView==='more')body=quickGrid(btn('작업대로','move-work','data-key="'+o.key+'"')+(s.moveUndo?.[o.key]?btn('이동 취소','undo-move','data-key="'+o.key+'"'):'')+btn('제자리로','move-home','data-key="'+o.key+'"')+btn('헹구기','wash','data-key="'+o.key+'"')+btn('행주로 닦기','wipe','data-key="'+o.key+'"')+btn('내용물 비우기','discard')+btn('사진 크게','photo'));
  else body=quickMain(o);
  return '<aside class="bar-popup bar-quick-popup" id="bar-panel" popover="manual" role="dialog" aria-label="'+esc(o.name)+' 사용"><div class="bar-popup-body">'+(panelView?'<div class="bar-quick-back">'+menuLink('← 이전','')+'</div>':'')+body+'</div></aside>';
 }
 function placePanel(){const pane=document.getElementById('bar-panel');if(!pane)return;const anchor=(selected==='@sink'?main.querySelector('.bar-sink-zone'):null)||main.querySelector('.bar-scene [data-object="'+selected+'"]')||main.querySelector('.bar-stock[data-object="'+selected+'"]');if(pane.showPopover&&!pane.matches(':popover-open'))pane.showPopover();if(!anchor)return;const vw=document.documentElement.clientWidth,vh=window.innerHeight;pane.style.maxWidth=Math.max(200,vw-24)+'px';const r=anchor.getBoundingClientRect(),p=pane.getBoundingClientRect();
 const rightSpace=vw-r.right,leftSpace=r.left;const x=rightSpace>=leftSpace?r.right+10:r.left-p.width-10;pane.style.left=Math.max(12,Math.min(vw-p.width-12,x))+'px';pane.style.top=Math.max(12,Math.min(vh-p.height-12,r.top))+'px';
 }
